DROP TRIGGER IF EXISTS trg_goal_created_gamification;
CREATE TRIGGER trg_goal_created_gamification AFTER INSERT ON goals FOR EACH ROW WHEN NEW.is_deleted = 0
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'goal_created', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, 5, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (5)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, 'FIRST_STEP', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created' AND source_id = NEW.id AND xp_awarded = -1)
  AND (SELECT COUNT(*) FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created') >= 1
  ON CONFLICT (user_id, badge_type) DO NOTHING;
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, k.bt, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p, (SELECT bt, req, kind FROM badge_rules) k
  WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created' AND source_id = NEW.id AND xp_awarded = -1) AND (CASE k.kind WHEN 's' THEN p.current_streak WHEN 'g' THEN p.goals_completed WHEN 'h' THEN p.habits_completed ELSE p.journal_entries_count END) >= k.req
  ON CONFLICT (user_id, badge_type) DO NOTHING;
UPDATE gamification_log SET xp_awarded = 5 WHERE user_id = NEW.user_id AND event_type = 'goal_created' AND source_id = NEW.id AND xp_awarded = -1;
END;

DROP TRIGGER IF EXISTS trg_goal_completed_gamification;
CREATE TRIGGER trg_goal_completed_gamification AFTER UPDATE ON goals FOR EACH ROW WHEN NEW.is_deleted = 0 AND NEW.status = 'COMPLETED' AND OLD.status <> 'COMPLETED'
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'goal_completed', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, 50, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (50)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE user_progress SET goals_completed = goals_completed + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = sync_version + 1 WHERE user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1);
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END), (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END))), strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM challenges c
  WHERE c.user_id = NEW.user_id AND c.challenge_type IN ('WEEKLY_GOALS','MONTHLY_COMPLETION') AND c.is_completed = 0 AND c.is_deleted = 0 AND c.end_date >= date('now') AND c.current_progress + 1 >= c.target_progress AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1) HAVING COUNT(*) > 0
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE challenges SET current_progress = current_progress + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'),
  sync_version = sync_version + 1 + (CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END),
  is_completed = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END,
  completed_at = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE completed_at END,
  xp_earned = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN CASE challenges.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END ELSE xp_earned END
  WHERE user_id = NEW.user_id AND challenge_type IN ('WEEKLY_GOALS','MONTHLY_COMPLETION') AND is_completed = 0 AND is_deleted = 0
  AND end_date >= date('now') AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1);
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, 'FIRST_STEP', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1)
  AND (SELECT COUNT(*) FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created') >= 1
  ON CONFLICT (user_id, badge_type) DO NOTHING;
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, k.bt, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p, (SELECT bt, req, kind FROM badge_rules) k
  WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1) AND (CASE k.kind WHEN 's' THEN p.current_streak WHEN 'g' THEN p.goals_completed WHEN 'h' THEN p.habits_completed ELSE p.journal_entries_count END) >= k.req
  ON CONFLICT (user_id, badge_type) DO NOTHING;
UPDATE gamification_log SET xp_awarded = 50 WHERE user_id = NEW.user_id AND event_type = 'goal_completed' AND source_id = NEW.id AND xp_awarded = -1;
END;

DROP TRIGGER IF EXISTS trg_milestone_completed_gamification;
CREATE TRIGGER trg_milestone_completed_gamification AFTER UPDATE ON milestones FOR EACH ROW WHEN NEW.is_deleted = 0 AND NEW.is_completed = 1 AND OLD.is_completed = 0
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'milestone_completed', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, 15, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (15)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'milestone_completed' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END), (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END))), strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM challenges c
  WHERE c.user_id = NEW.user_id AND c.challenge_type IN ('WEEKLY_MILESTONE') AND c.is_completed = 0 AND c.is_deleted = 0 AND c.end_date >= date('now') AND c.current_progress + 1 >= c.target_progress AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'milestone_completed' AND source_id = NEW.id AND xp_awarded = -1) HAVING COUNT(*) > 0
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE challenges SET current_progress = current_progress + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'),
  sync_version = sync_version + 1 + (CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END),
  is_completed = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END,
  completed_at = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE completed_at END,
  xp_earned = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN CASE challenges.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END ELSE xp_earned END
  WHERE user_id = NEW.user_id AND challenge_type IN ('WEEKLY_MILESTONE') AND is_completed = 0 AND is_deleted = 0
  AND end_date >= date('now') AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'milestone_completed' AND source_id = NEW.id AND xp_awarded = -1);
UPDATE gamification_log SET xp_awarded = 15 WHERE user_id = NEW.user_id AND event_type = 'milestone_completed' AND source_id = NEW.id AND xp_awarded = -1;
END;

DROP TRIGGER IF EXISTS trg_journal_entry_gamification;
CREATE TRIGGER trg_journal_entry_gamification AFTER INSERT ON journal_entries FOR EACH ROW WHEN NEW.is_deleted = 0
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'journal_entry', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, 10, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (10)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE user_progress SET journal_entries_count = journal_entries_count + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = sync_version + 1 WHERE user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1);
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END), (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (SUM(CASE c.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END))), strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM challenges c
  WHERE c.user_id = NEW.user_id AND c.challenge_type IN ('DAILY_JOURNAL','WEEKLY_JOURNAL') AND c.is_completed = 0 AND c.is_deleted = 0 AND c.end_date >= date('now') AND c.current_progress + 1 >= c.target_progress AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1) HAVING COUNT(*) > 0
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE challenges SET current_progress = current_progress + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'),
  sync_version = sync_version + 1 + (CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END),
  is_completed = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN 1 ELSE 0 END,
  completed_at = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') ELSE completed_at END,
  xp_earned = CASE WHEN challenges.current_progress + 1 >= challenges.target_progress THEN CASE challenges.challenge_type WHEN 'DAILY_CHECK_IN' THEN 10 WHEN 'DAILY_JOURNAL' THEN 15 WHEN 'DAILY_HABIT' THEN 20 WHEN 'WEEKLY_GOALS' THEN 50 WHEN 'WEEKLY_HABITS' THEN 75 WHEN 'WEEKLY_JOURNAL' THEN 50 WHEN 'WEEKLY_MILESTONE' THEN 60 WHEN 'MONTHLY_COMPLETION' THEN 200 WHEN 'MONTHLY_STREAK' THEN 300 WHEN 'MONTHLY_BALANCED' THEN 250 WHEN 'PERFECT_DAY' THEN 100 WHEN 'CATEGORY_FOCUS' THEN 150 WHEN 'EARLY_RISER' THEN 100 ELSE 0 END ELSE xp_earned END
  WHERE user_id = NEW.user_id AND challenge_type IN ('DAILY_JOURNAL','WEEKLY_JOURNAL') AND is_completed = 0 AND is_deleted = 0
  AND end_date >= date('now') AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1);
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, 'FIRST_STEP', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1)
  AND (SELECT COUNT(*) FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'goal_created') >= 1
  ON CONFLICT (user_id, badge_type) DO NOTHING;
INSERT INTO badges (id, user_id, badge_type, earned_at, is_new, updated_at, is_deleted, sync_version)
  SELECT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), NEW.user_id, k.bt, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'), 0, 0 FROM user_progress p, (SELECT bt, req, kind FROM badge_rules) k
  WHERE p.user_id = NEW.user_id AND EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1) AND (CASE k.kind WHEN 's' THEN p.current_streak WHEN 'g' THEN p.goals_completed WHEN 'h' THEN p.habits_completed ELSE p.journal_entries_count END) >= k.req
  ON CONFLICT (user_id, badge_type) DO NOTHING;
UPDATE gamification_log SET xp_awarded = 10 WHERE user_id = NEW.user_id AND event_type = 'journal_entry' AND source_id = NEW.id AND xp_awarded = -1;
END;

