DROP TRIGGER IF EXISTS trg_focus_session_insert_gamification;
CREATE TRIGGER trg_focus_session_insert_gamification AFTER INSERT ON focus_sessions FOR EACH ROW WHEN NEW.is_deleted = 0 AND NEW.was_completed = 1
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'focus_session', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 60 THEN 40 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 45 THEN 30 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 25 THEN 20 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 15 THEN 10 WHEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) > 1 THEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) ELSE 1 END), (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= ((CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 60 THEN 40 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 45 THEN 30 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 25 THEN 20 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 15 THEN 10 WHEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) > 1 THEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) ELSE 1 END))), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'focus_session' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
