  ON CONFLICT (user_id, badge_type) DO NOTHING;
UPDATE gamification_log SET xp_awarded = (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 60 THEN 40 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 45 THEN 30 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 25 THEN 20 WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) >= 15 THEN 10 WHEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) > 1 THEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) ELSE 1 END) WHERE user_id = NEW.user_id AND event_type = 'focus_session' AND source_id = NEW.id AND xp_awarded = -1;
END;

