ration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) > 1 THEN (CASE WHEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 WHEN ((CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2) % 2 = 0 THEN (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 ELSE (CASE WHEN NEW.planned_duration_minutes = 0 AND NEW.actual_duration_seconds > 0 THEN NEW.actual_duration_seconds / 60 ELSE NEW.planned_duration_minutes END) / 2 + 1 END) ELSE 1 END))), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'focus_session' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
