DROP TRIGGER IF EXISTS trg_beginner_objective_completed_insert;
CREATE TRIGGER trg_beginner_objective_completed_insert AFTER INSERT ON beginner_objectives FOR EACH ROW WHEN NEW.is_completed = 1 AND NEW.xp_awarded > 0
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'objective_completed', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, NEW.xp_awarded, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (NEW.xp_awarded)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'objective_completed' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE gamification_log SET xp_awarded = NEW.xp_awarded WHERE user_id = NEW.user_id AND event_type = 'objective_completed' AND source_id = NEW.id AND xp_awarded = -1;
END;

DROP TRIGGER IF EXISTS trg_beginner_objective_completed;
CREATE TRIGGER trg_beginner_objective_completed AFTER UPDATE ON beginner_objectives FOR EACH ROW WHEN NEW.is_completed = 1 AND OLD.is_completed = 0 AND NEW.xp_awarded > 0
BEGIN
INSERT INTO gamification_log (user_id, event_type, source_id, xp_awarded) VALUES (NEW.user_id, 'objective_completed', NEW.id, -1) ON CONFLICT (user_id, event_type, source_id) DO NOTHING;
INSERT INTO user_progress (user_id, total_xp, current_level, updated_at)
  SELECT NEW.user_id, NEW.xp_awarded, (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (NEW.xp_awarded)), strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS (SELECT 1 FROM gamification_log WHERE user_id = NEW.user_id AND event_type = 'objective_completed' AND source_id = NEW.id AND xp_awarded = -1)
  ON CONFLICT (user_id) DO UPDATE SET total_xp = user_progress.total_xp + excluded.total_xp,
    current_level = (SELECT MAX(level) FROM level_thresholds WHERE min_xp <= (user_progress.total_xp + excluded.total_xp)),
    updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), sync_version = user_progress.sync_version + 1;
UPDATE gamification_log SET xp_awarded = NEW.xp_awarded WHERE user_id = NEW.user_id AND event_type = 'objective_completed' AND source_id = NEW.id AND xp_awarded = -1;
END;
